#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
MFP-3 ONE FILE v1.16 — REGIME RESIDUAL OVERLAY
===============================================

Mantiene toda la cadena anterior, pero corrige la lógica de v1.15.

Problema v1.15:
- usaba 100% v1.7 como punto de contracción;
- la histéresis impedía aplicar ajustes pequeños;
- terminó casi siempre en v1.7=100%, Synergy=0%.

v1.16:
- toma como BASE la mezcla walk-forward de v1.14;
- aprende sólo un DELTA condicionado por régimen;
- delta=0 significa "no tengo evidencia para modificar v1.14";
- jamás obliga a volver a 100% v1.7 por falta de evidencia;
- todos los deltas se eligen usando únicamente datos pasados.

Peso final:
    W_v17_final(t) = clip(W_v14(t) + Delta_regimen(t), 0.50, 1.00)

No modifica v1.7-FROZEN.
No ejecuta operaciones reales.

Uso:
    py mfp3_onefile_v1_16.py
    py mfp3_onefile_v1_16.py --overlay
    py mfp3_onefile_v1_16.py --install
    py mfp3_onefile_v1_16.py --status
"""

from __future__ import annotations

import argparse
import base64
import json
import os
import subprocess
import sys
import zlib
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd

V115_B64 = """"""

def embedded_source(blob: str) -> str:
    return zlib.decompress(base64.b64decode(blob)).decode("utf-8")

V115_SOURCE = embedded_source(V115_B64)

ROOT = Path(".")
LAB = ROOT / "mfp3_regime_overlay_lab"
LAB.mkdir(exist_ok=True)

V14_DAILY = ROOT / "mfp3_fusion_lab" / "fusion_daily.csv"

OUT_DAILY = LAB / "regime_overlay_daily.csv"
OUT_DECISIONS = LAB / "regime_overlay_decisions.csv"
OUT_METRICS = LAB / "regime_overlay_metrics.csv"
OUT_STATE = LAB / "regime_overlay_state.json"

INITIAL_CAPITAL = 10_000_000.0

# Delta sobre el peso de v1.7 aprendido por v1.14.
DELTAS = [-0.15, -0.10, -0.05, 0.0, 0.05, 0.10]
TRAIN_WINDOWS = [252, 504, 756]

MIN_TRAIN = 252
MIN_REGIME_DAYS = 60
SHRINK_K = 140.0

# Sólo evita micro-ajustes del overlay. El peso base v1.14 puede seguir cambiando.
DELTA_HYSTERESIS = 0.025

TASK_NAME = "MFP3_ONEFILE_V116_DAILY"
RUN_EVERY_DAYS = 14

# ---------------------------------------------------------------------
# Run v1.15 chain
# ---------------------------------------------------------------------

def run_v115(args):
    old = sys.argv[:]
    try:
        sys.argv = ["mfp3_v115_embedded.py"]
        if args.full:
            sys.argv.append("--full")

        g = {
            "__name__": "mfp3_v115_embedded",
            "__file__": "<embedded:v1.15>",
            "__builtins__": __builtins__,
        }

        exec(
            compile(V115_SOURCE, g["__file__"], "exec"),
            g,
            g,
        )
        g["main"]()
    finally:
        sys.argv = old

# ---------------------------------------------------------------------
# Scheduler
# ---------------------------------------------------------------------

def install_this_file():
    if os.name != "nt":
        raise SystemExit("--install sólo funciona en Windows.")

    script = str(Path(__file__).resolve())
    python = str(Path(sys.executable).resolve())
    action = f'"{python}" "{script}"'

    p = subprocess.run(
        [
            "schtasks", "/Create",
            "/TN", TASK_NAME,
            "/TR", action,
            "/SC", "DAILY",
            "/ST", "18:30",
            "/F",
        ],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )

    if p.returncode != 0:
        print(p.stdout)
        print(p.stderr)
        raise SystemExit("No se pudo instalar la tarea.")

    print(p.stdout.strip())
    print("Instalado: v1.16 se ejecutará diariamente a las 18:30.")

def uninstall_this_file():
    if os.name != "nt":
        raise SystemExit("--uninstall sólo funciona en Windows.")

    p = subprocess.run(
        ["schtasks", "/Delete", "/TN", TASK_NAME, "/F"],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    print((p.stdout or p.stderr).strip())

# ---------------------------------------------------------------------
# Metrics
# ---------------------------------------------------------------------

def perf(ret):
    r = pd.Series(ret).fillna(0.0)

    if len(r) == 0:
        return {
            "total_return": 0.0,
            "cagr": 0.0,
            "sharpe": 0.0,
            "max_drawdown": 0.0,
            "ann_vol": 0.0,
        }

    curve = (1 + r).cumprod()
    total = float(curve.iloc[-1] - 1.0)
    years = max(len(r) / 252.0, 1 / 252.0)
    cagr = float(curve.iloc[-1] ** (1.0 / years) - 1.0)

    vol = float(r.std() * np.sqrt(252))
    sharpe = float(r.mean() * 252 / vol) if vol > 1e-12 else 0.0

    dd = curve / curve.cummax() - 1.0

    return {
        "total_return": total,
        "cagr": cagr,
        "sharpe": sharpe,
        "max_drawdown": float(dd.min()),
        "ann_vol": vol,
    }

def utility(ret):
    p = perf(ret)

    # Reward return/risk and penalize deep losses.
    u = (
        p["sharpe"]
        + 0.40 * p["cagr"]
        - 0.60 * abs(p["max_drawdown"])
    )

    return u, p

# ---------------------------------------------------------------------
# Data
# ---------------------------------------------------------------------

def load_base():
    if not V14_DAILY.exists():
        raise RuntimeError(
            "Falta mfp3_fusion_lab/fusion_daily.csv. "
            "Ejecuta primero la cadena hasta v1.14."
        )

    x = pd.read_csv(
        V14_DAILY,
        index_col=0,
        parse_dates=True,
    ).sort_index()

    required = {
        "v17_ret",
        "synergy_ret",
        "benchmark_ret",
        "v17_weight",
        "fusion_ret",
    }

    missing = required - set(x.columns)

    if missing:
        raise RuntimeError(
            f"Faltan columnas requeridas en fusion_daily.csv: {missing}"
        )

    return x

# ---------------------------------------------------------------------
# Regime features — shifted to avoid same-day information
# ---------------------------------------------------------------------

def compound_ret(s, n):
    return (
        (1 + s.fillna(0.0))
        .rolling(n)
        .apply(np.prod, raw=True)
        - 1.0
    )

def drawdown_series(ret):
    curve = (1 + ret.fillna(0.0)).cumprod()
    return curve / curve.cummax() - 1.0

def build_features(x):
    f = pd.DataFrame(index=x.index)

    bm = x["benchmark_ret"].fillna(0.0)
    v17 = x["v17_ret"].fillna(0.0)
    syn = x["synergy_ret"].fillna(0.0)

    for n in [21, 63, 126]:
        f[f"bm_ret_{n}"] = compound_ret(bm, n)
        f[f"v17_ret_{n}"] = compound_ret(v17, n)
        f[f"syn_ret_{n}"] = compound_ret(syn, n)
        f[f"edge_v17_syn_{n}"] = (
            f[f"v17_ret_{n}"] - f[f"syn_ret_{n}"]
        )

    for n in [21, 63]:
        f[f"bm_vol_{n}"] = (
            bm.rolling(n).std() * np.sqrt(252)
        )
        f[f"v17_vol_{n}"] = (
            v17.rolling(n).std() * np.sqrt(252)
        )
        f[f"syn_vol_{n}"] = (
            syn.rolling(n).std() * np.sqrt(252)
        )
        f[f"corr_v17_syn_{n}"] = (
            v17.rolling(n).corr(syn)
        )

    f["bm_dd"] = drawdown_series(bm)
    f["v17_dd"] = drawdown_series(v17)
    f["syn_dd"] = drawdown_series(syn)

    # Decision at date t may use only information through t-1.
    return f.shift(1)

# ---------------------------------------------------------------------
# Regime labels with expanding historical quantiles
# ---------------------------------------------------------------------

def classify_regimes(features):
    out = pd.Series(
        "NEUTRAL",
        index=features.index,
        dtype=object,
    )

    for i, dt in enumerate(features.index):
        if i < 126:
            continue

        row = features.iloc[i]
        past = features.iloc[:i]

        hist_vol = pd.to_numeric(
            past["bm_vol_21"],
            errors="coerce",
        ).dropna()

        if len(hist_vol) < 60:
            continue

        q75 = float(hist_vol.quantile(0.75))
        q40 = float(hist_vol.quantile(0.40))

        vol = float(row.get("bm_vol_21", np.nan))
        bm63 = float(row.get("bm_ret_63", np.nan))
        bmdd = float(row.get("bm_dd", np.nan))
        v17dd = float(row.get("v17_dd", np.nan))

        risk_off = (
            (np.isfinite(bm63) and bm63 < -0.05)
            or (np.isfinite(bmdd) and bmdd < -0.08)
            or (np.isfinite(v17dd) and v17dd < -0.10)
            or (
                np.isfinite(vol)
                and vol > q75
            )
        )

        risk_on = (
            np.isfinite(bm63)
            and bm63 > 0.04
            and np.isfinite(bmdd)
            and bmdd > -0.04
            and np.isfinite(vol)
            and vol <= q40
        )

        if risk_off:
            out.loc[dt] = "RISK_OFF"
        elif risk_on:
            out.loc[dt] = "RISK_ON"
        else:
            out.loc[dt] = "NEUTRAL"

    return out

# ---------------------------------------------------------------------
# Residual overlay
# ---------------------------------------------------------------------

def returns_with_delta(frame, delta):
    base_w = pd.to_numeric(
        frame["v17_weight"],
        errors="coerce",
    ).fillna(1.0)

    w = (base_w + float(delta)).clip(0.50, 1.00)

    return (
        w * frame["v17_ret"]
        + (1.0 - w) * frame["synergy_ret"]
    )

def evaluate_deltas(history, history_regimes, regime):
    rows = []

    for window in TRAIN_WINDOWS:
        z = history.tail(window)

        if len(z) < min(window, MIN_TRAIN):
            continue

        rz = history_regimes.reindex(z.index)
        same = z[rz == regime]

        for delta in DELTAS:
            global_ret = returns_with_delta(
                z,
                delta,
            )
            global_u, global_p = utility(
                global_ret
            )

            if len(same) >= MIN_REGIME_DAYS:
                regime_ret = returns_with_delta(
                    same,
                    delta,
                )
                regime_u, regime_p = utility(
                    regime_ret
                )

                n = len(same)
                reliability = (
                    n / (n + SHRINK_K)
                )

                score = (
                    reliability * regime_u
                    + (1.0 - reliability) * global_u
                )
            else:
                regime_u = np.nan
                n = len(same)
                reliability = 0.0
                score = global_u

            # Very small penalty for large overlay adjustments.
            score -= 0.025 * abs(delta)

            rows.append({
                "window": window,
                "regime": regime,
                "delta": delta,
                "score": score,
                "global_utility": global_u,
                "regime_utility": regime_u,
                "same_regime_days": n,
                "reliability": reliability,
                "global_sharpe": global_p["sharpe"],
                "global_drawdown": global_p["max_drawdown"],
            })

    return pd.DataFrame(rows)

def choose_delta(tab):
    if tab.empty:
        return 0.0, tab

    top = tab.sort_values(
        ["score", "global_sharpe"],
        ascending=False,
    ).head(4).copy()

    s = top["score"].to_numpy(dtype=float)
    s = s - np.nanmax(s)

    p = np.exp(s / 0.08)
    p = p / p.sum()

    top["ensemble_weight"] = p

    raw_delta = float(
        np.sum(
            top["delta"].to_numpy(dtype=float)
            * p
        )
    )

    # Shrink DELTA toward 0, not toward 100% v1.7.
    reliability = float(
        top["reliability"].max()
    )

    target_delta = (
        reliability * raw_delta
    )

    return float(
        np.clip(
            target_delta,
            min(DELTAS),
            max(DELTAS),
        )
    ), top

# ---------------------------------------------------------------------
# Walk-forward
# ---------------------------------------------------------------------

def month_firsts(index):
    s = pd.Series(
        np.arange(len(index)),
        index=index,
    )
    return set(
        s.groupby(
            [index.year, index.month]
        ).head(1).index
    )

def run_overlay():
    x = load_base()
    features = build_features(x)
    regimes = classify_regimes(features)

    firsts = month_firsts(x.index)

    current_delta = 0.0

    applied_delta = pd.Series(
        0.0,
        index=x.index,
        dtype=float,
    )

    decisions = []

    for i, dt in enumerate(x.index):
        if i < MIN_TRAIN:
            applied_delta.loc[dt] = current_delta
            continue

        if dt in firsts:
            history = x.iloc[:i]
            hist_regimes = regimes.iloc[:i]
            regime = str(regimes.loc[dt])

            tab = evaluate_deltas(
                history,
                hist_regimes,
                regime,
            )

            target_delta, top = choose_delta(
                tab
            )

            if (
                abs(target_delta - current_delta)
                >= DELTA_HYSTERESIS
            ):
                new_delta = target_delta
            else:
                new_delta = current_delta

            base_weight_today = float(
                x.loc[dt, "v17_weight"]
            )

            final_weight_today = float(
                np.clip(
                    base_weight_today + new_delta,
                    0.50,
                    1.00,
                )
            )

            decisions.append({
                "date": dt,
                "regime": regime,
                "base_v14_v17_weight":
                    base_weight_today,
                "previous_delta":
                    current_delta,
                "target_delta":
                    target_delta,
                "applied_delta":
                    new_delta,
                "final_v17_weight":
                    final_weight_today,
                "final_synergy_weight":
                    1.0 - final_weight_today,
                "best_window":
                    int(top.iloc[0]["window"])
                    if len(top) else np.nan,
                "best_candidate_delta":
                    float(top.iloc[0]["delta"])
                    if len(top) else np.nan,
                "regime_reliability":
                    float(top["reliability"].max())
                    if len(top) else 0.0,
            })

            current_delta = new_delta

        applied_delta.loc[dt] = (
            current_delta
        )

    out = x.copy()
    out["regime_overlay"] = regimes
    out["overlay_delta"] = (
        applied_delta.ffill().fillna(0.0)
    )

    out["v17_weight_overlay"] = (
        out["v17_weight"]
        + out["overlay_delta"]
    ).clip(0.50, 1.00)

    out["synergy_weight_overlay"] = (
        1.0 - out["v17_weight_overlay"]
    )

    out["overlay_ret"] = (
        out["v17_weight_overlay"]
        * out["v17_ret"]
        + out["synergy_weight_overlay"]
        * out["synergy_ret"]
    )

    out["capital_overlay"] = (
        INITIAL_CAPITAL
        * (1 + out["overlay_ret"]).cumprod()
    )

    out["capital_v14"] = (
        INITIAL_CAPITAL
        * (1 + out["fusion_ret"]).cumprod()
    )

    out["capital_v17"] = (
        INITIAL_CAPITAL
        * (1 + out["v17_ret"]).cumprod()
    )

    out["capital_synergy"] = (
        INITIAL_CAPITAL
        * (1 + out["synergy_ret"]).cumprod()
    )

    out["capital_benchmark"] = (
        INITIAL_CAPITAL
        * (1 + out["benchmark_ret"]).cumprod()
    )

    metrics = pd.DataFrame([
        {
            "name": "REGIME_RESIDUAL_OVERLAY_CHALLENGER",
            **perf(out["overlay_ret"]),
        },
        {
            "name": "V14_ADAPTIVE_FUSION_REFERENCE",
            **perf(out["fusion_ret"]),
        },
        {
            "name": "V17_REFERENCE_COMMON_WINDOW",
            **perf(out["v17_ret"]),
        },
        {
            "name": "SYNERGY_REFERENCE_COMMON_WINDOW",
            **perf(out["synergy_ret"]),
        },
        {
            "name": "BENCHMARK_COMMON_WINDOW",
            **perf(out["benchmark_ret"]),
        },
    ])

    decisions_df = pd.DataFrame(
        decisions
    )

    out.to_csv(
        OUT_DAILY,
        encoding="utf-8-sig",
    )

    decisions_df.to_csv(
        OUT_DECISIONS,
        index=False,
        encoding="utf-8-sig",
    )

    metrics.to_csv(
        OUT_METRICS,
        index=False,
        encoding="utf-8-sig",
    )

    OUT_STATE.write_text(
        json.dumps(
            {
                "last_completed_utc":
                    datetime.now(timezone.utc)
                    .isoformat(timespec="seconds"),
                "version": "v1.16",
                "latest_regime":
                    str(out["regime_overlay"].iloc[-1]),
                "latest_base_v14_v17_weight":
                    float(out["v17_weight"].iloc[-1]),
                "latest_overlay_delta":
                    float(out["overlay_delta"].iloc[-1]),
                "latest_final_v17_weight":
                    float(out["v17_weight_overlay"].iloc[-1]),
                "latest_final_synergy_weight":
                    float(out["synergy_weight_overlay"].iloc[-1]),
            },
            indent=2,
        ),
        encoding="utf-8",
    )

    return out, decisions_df, metrics

# ---------------------------------------------------------------------
# Cadence
# ---------------------------------------------------------------------

def overlay_due(force=False):
    if force or not OUT_STATE.exists():
        return True

    try:
        s = json.loads(
            OUT_STATE.read_text(
                encoding="utf-8"
            )
        )

        last = pd.Timestamp(
            s["last_completed_utc"]
        )

        if last.tzinfo is None:
            last = last.tz_localize("UTC")
        else:
            last = last.tz_convert("UTC")

        return (
            pd.Timestamp.now(tz="UTC") - last
        ).days >= RUN_EVERY_DAYS

    except Exception:
        return True

# ---------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------

def main():
    p = argparse.ArgumentParser()
    p.add_argument("--overlay", action="store_true")
    p.add_argument("--install", action="store_true")
    p.add_argument("--uninstall", action="store_true")
    p.add_argument("--status", action="store_true")
    p.add_argument("--full", action="store_true")
    args = p.parse_args()

    if args.install:
        install_this_file()
        return

    if args.uninstall:
        uninstall_this_file()
        return

    if args.status:
        print("\nMFP-3 v1.16 STATUS")
        print("Overlay Lab:", LAB.resolve())
        print("Overlay due:", overlay_due(False))
        print("Metrics:", OUT_METRICS.exists())
        print("Decisions:", OUT_DECISIONS.exists())
        return

    print("\n" + "=" * 100)
    print("MFP-3 ONE FILE v1.16 — REGIME RESIDUAL OVERLAY")
    print("=" * 100)

    run_v115(args)

    if overlay_due(args.overlay):
        print(
            "\n[v1.16] Aprendiendo DELTA por régimen sobre "
            "la mezcla v1.14..."
        )

        out, decisions, metrics = run_overlay()

        print("\n" + "=" * 100)
        print("REGIME RESIDUAL OVERLAY — RESULTADO")
        print("=" * 100)

        with pd.option_context(
            "display.max_columns",
            None,
            "display.width",
            200,
        ):
            print(metrics)

        print(
            "\nCapital Overlay:",
            f"${out['capital_overlay'].iloc[-1]:,.0f} CLP"
        )
        print(
            "Capital v1.14:",
            f"${out['capital_v14'].iloc[-1]:,.0f} CLP"
        )
        print(
            "Capital v1.7:",
            f"${out['capital_v17'].iloc[-1]:,.0f} CLP"
        )
        print(
            "Capital Synergy:",
            f"${out['capital_synergy'].iloc[-1]:,.0f} CLP"
        )
        print(
            "Capital Benchmark:",
            f"${out['capital_benchmark'].iloc[-1]:,.0f} CLP"
        )

        print("\nEstado actual:")
        print(
            "  Régimen:",
            out["regime_overlay"].iloc[-1]
        )
        print(
            "  Base v1.14 v1.7:",
            f"{out['v17_weight'].iloc[-1]:.1%}"
        )
        print(
            "  Delta régimen:",
            f"{out['overlay_delta'].iloc[-1]:+.1%}"
        )
        print(
            "  v1.7 final:",
            f"{out['v17_weight_overlay'].iloc[-1]:.1%}"
        )
        print(
            "  Synergy final:",
            f"{out['synergy_weight_overlay'].iloc[-1]:.1%}"
        )

        if len(decisions):
            print(
                "\nÚltimas decisiones del overlay:"
            )
            with pd.option_context(
                "display.max_columns",
                None,
                "display.width",
                210,
            ):
                print(
                    decisions.tail(10)
                )

    else:
        print(
            "\n[v1.16] Overlay ya está actualizado. "
            "Se repite automáticamente cada 14 días."
        )

    print(
        "\nRegime Residual Overlay sigue siendo Challenger. "
        "v1.7-FROZEN y su Forward Paper permanecen intactos."
    )

if __name__ == "__main__":
    main()
